var toISODate=function(date){var d=new Date(date);var y=d.getFullYear();var m=String(d.getMonth()+1).padStart(2,"0");var day=String(d.getDate()).padStart(2,"0");return`${y}-${m}-${day}`;};var addDaysISO=function(days){var d=new Date();d.setDate(d.getDate()+days);return toISODate(d);};var addMonthsISO=function(months){var d=new Date();d.setMonth(d.getMonth()+months);return toISODate(d);};var resolveTaskDueDate=function(option){if(!option||option.id==="none")return null;if(option.iso)return option.iso;if(option.id==="today")return toISODate(new Date());if(option.id==="tomorrow")return addDaysISO(1);if(option.id==="after")return addDaysISO(2);if(option.id==="1w")return addDaysISO(7);if(option.id==="1m")return addMonthsISO(1);return null;};var computeTaskCounts=function(tasks){var active=(tasks||[]).filter(function(t){return!t.archived;});return{all:active.length,today:active.filter(function(t){return t.time&&t.time.startsWith("오늘")&&!t.done;}).length,overdue:active.filter(function(t){return t.time==="어제"&&!t.done;}).length,important:active.filter(function(t){return t.priority==="high"&&!t.done;}).length,reminders:active.filter(function(t){return t.reminder&&!t.done;}).length,completed:active.filter(function(t){return t.done;}).length};};var filterTasks=function(tasks,filterId,searchQuery){var q=String(searchQuery||"").trim().toLowerCase();return(tasks||[]).filter(function(t){return!t.archived;}).filter(function(t){if(filterId==="today")return t.time&&t.time.startsWith("오늘")&&!t.done;if(filterId==="overdue")return t.time==="어제"&&!t.done;if(filterId==="important")return t.priority==="high"&&!t.done;if(filterId==="reminders")return t.reminder&&!t.done;if(filterId==="completed")return t.done;return true;}).filter(function(t){if(!q)return true;var titleMatch=(t.title||"").toLowerCase().includes(q);var memoMatch=(t.memo||"").toLowerCase().includes(q);var tagMatch=Array.isArray(t.tags)&&t.tags.some(function(tag){return tag.toLowerCase().includes(q);});return titleMatch||memoMatch||tagMatch;});};var computeKanbanBuckets=function(filteredTasks){return{today:(filteredTasks||[]).filter(function(t){return t.time&&t.time.startsWith("오늘")&&!t.done;}),week:(filteredTasks||[]).filter(function(t){return t.time&&!t.time.startsWith("오늘")&&t.time!=="어제"&&t.time!=="보관"&&!t.done;}),later:(filteredTasks||[]).filter(function(t){return!t.done&&(!t.time||t.time==="보관"||t.time.startsWith("어제"));}),done:(filteredTasks||[]).filter(function(t){return t.done;})};};var sortTasksByPriority=function(tasks){var order={high:0,med:1,low:2};return[...(tasks||[])].sort(function(a,b){if(a.done!==b.done)return a.done?1:-1;return(order[a.priority]??1)-(order[b.priority]??1);});};var computeProjectStats=function(project,tasks){if(!project)return{totalCount:0,openCount:0,doneCount:0,progress:0,courseCount:0};var projTasks=(tasks||[]).filter(function(t){return t.project===project.id&&!t.archived;});var openCount=projTasks.filter(function(t){return!t.done;}).length;var doneCount=projTasks.filter(function(t){return t.done;}).length;var totalCount=projTasks.length;var progress=totalCount>0?Math.round(doneCount/totalCount*100):0;var courseCount=new Set(projTasks.map(function(t){return t.course||t._raw&&t._raw.courseTitle||(t.source==="eclass-course"?t.title:null);}).filter(Boolean)).size;return{totalCount,openCount,doneCount,progress,courseCount};};var parseMemoSubtasks=function(memo){if(!memo)return{cleanMemo:"",subtasks:[]};var lines=String(memo).split(/\r?\n/);var cleanLines=[];var subtasks=[];var inChecklist=false;for(var i=0;i<lines.length;i++){var line=lines[i];var trimmed=line.trim();if(trimmed==="[체크리스트]"){inChecklist=true;continue;}var match=trimmed.match(/^-\s*\[([ xX])\]\s*(.+)$/);if(match){subtasks.push({id:"st_"+Math.random().toString(36).slice(2,8),done:match[1].toLowerCase()==="x",text:match[2].trim()});}else{if(!inChecklist)cleanLines.push(line);}}return{cleanMemo:cleanLines.join("\n").trim(),subtasks:subtasks};};var serializeMemoSubtasks=function(cleanMemo,subtasks){var parts=[];if(cleanMemo&&String(cleanMemo).trim())parts.push(String(cleanMemo).trim());if(Array.isArray(subtasks)&&subtasks.length>0){var lines=["[체크리스트]"];for(var i=0;i<subtasks.length;i++){var st=subtasks[i];if(st&&st.text&&String(st.text).trim()){lines.push("- ["+(st.done?"x":" ")+"] "+String(st.text).trim());}}if(lines.length>1)parts.push(lines.join("\n"));}return parts.join("\n\n");};var CommandDispatcher=function(api){this.api=api;};CommandDispatcher.prototype.dispatch=async function(commandName,payload){if(this.api&&typeof this.api[commandName]==="function"){return await this.api[commandName](payload);}if(typeof window!=="undefined"){window.dispatchEvent(new CustomEvent(`planary:${commandName}`,{detail:payload}));return true;}throw new Error(`Command ${commandName} handler not found`);};window.PlanaryVM=Object.assign(window.PlanaryVM||{},{toISODate,addDaysISO,addMonthsISO,resolveTaskDueDate,computeTaskCounts,filterTasks,computeKanbanBuckets,sortTasksByPriority,computeProjectStats,CommandDispatcher,parseMemoSubtasks,serializeMemoSubtasks});